const { GeneralChat } = require('../../models/chat/general_chat.model');
const { User } = require('../../models/user/user.model');
const { Op } = require('sequelize');

class GeneralChatRepository {
    
    // Créer un nouveau message
    async create(messageData) {
        try {
            return await GeneralChat.create(messageData);
        } catch (error) {
            console.error('Erreur lors de la création du message:', error);
            throw error;
        }
    }

    // Récupérer l'historique des messages avec pagination
    async getChatHistory(limit = 50, offset = 0) {
        try {
            const messages = await GeneralChat.findAll({
                where: {
                    is_deleted: false
                },
                include: [
                    {
                        model: User,
                        attributes: ['id_user', 'pseudo', 'photo'], // Seulement les infos nécessaires
                        as: 'user'
                    }
                ],
                order: [['createdAt', 'DESC']], // Messages les plus récents en premier
                limit: limit,
                offset: offset
            });

            // Convertir en objets JSON propres pour éviter les références circulaires
            const cleanMessages = messages.map(message => {
                const messageJson = message.toJSON();
                return {
                    id_message: messageJson.id_message,
                    message: messageJson.message,
                    user: {
                        id_user: messageJson.user?.id_user || null,
                        pseudo: messageJson.user?.pseudo || 'Utilisateur inconnu',
                        photo: messageJson.user?.photo || null
                    },
                    timestamp: messageJson.createdAt,
                    createdAt: messageJson.createdAt,
                    edited_at: messageJson.edited_at
                };
            });

            // Inverser l'ordre pour avoir les plus anciens en premier dans le chat
            return cleanMessages.reverse();
        } catch (error) {
            console.error('Erreur lors de la récupération de l\'historique:', error);
            throw error;
        }
    }

    // Récupérer les messages récents (pour les nouveaux utilisateurs qui rejoignent)
    async getRecentMessages(limit = 20) {
        try {
            const messages = await GeneralChat.findAll({
                where: {
                    is_deleted: false,
                    createdAt: {
                        [Op.gte]: new Date(Date.now() - 24 * 60 * 60 * 1000) // Dernières 24h
                    }
                },
                include: [
                    {
                        model: User,
                        attributes: ['id_user', 'pseudo', 'photo'],
                        as: 'user'
                    }
                ],
                order: [['createdAt', 'ASC']], // Ordre chronologique
                limit: limit
            });

            // Convertir en objets JSON propres
            const cleanMessages = messages.map(message => {
                const messageJson = message.toJSON();
                return {
                    id_message: messageJson.id_message,
                    message: messageJson.message,
                    user: {
                        id_user: messageJson.user?.id_user || null,
                        pseudo: messageJson.user?.pseudo || 'Utilisateur inconnu',
                        photo: messageJson.user?.photo || null
                    },
                    timestamp: messageJson.createdAt,
                    createdAt: messageJson.createdAt,
                    edited_at: messageJson.edited_at
                };
            });

            return cleanMessages;
        } catch (error) {
            console.error('Erreur lors de la récupération des messages récents:', error);
            throw error;
        }
    }

    // Récupérer un message par ID
    async findById(messageId) {
        try {
            const message = await GeneralChat.findByPk(messageId, {
                include: [
                    {
                        model: User,
                        attributes: ['id_user', 'pseudo', 'photo'],
                        as: 'user'
                    }
                ]
            });

            if (!message) {
                return null;
            }

            // Convertir en objet JSON propre
            const messageJson = message.toJSON();
            return {
                id_message: messageJson.id_message,
                message: messageJson.message,
                user: {
                    id_user: messageJson.user?.id_user || null,
                    pseudo: messageJson.user?.pseudo || 'Utilisateur inconnu',
                    photo: messageJson.user?.photo || null
                },
                timestamp: messageJson.createdAt,
                createdAt: messageJson.createdAt,
                edited_at: messageJson.edited_at
            };
        } catch (error) {
            console.error('Erreur lors de la récupération du message:', error);
            throw error;
        }
    }

    // Modifier un message
    async updateMessage(messageId, userId, newMessage) {
        try {
            const message = await GeneralChat.findOne({
                where: {
                    id_message: messageId,
                    id_user: userId,
                    is_deleted: false
                }
            });

            if (!message) {
                throw new Error('Message non trouvé ou vous n\'êtes pas autorisé à le modifier');
            }

            // Vérifier que le message n'est pas trop ancien (ex: 5 minutes)
            const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000);
            if (message.createdAt < fiveMinutesAgo) {
                throw new Error('Vous ne pouvez plus modifier ce message (délai dépassé)');
            }

            await message.update({
                message: newMessage,
                edited_at: new Date()
            });

            return await this.findById(messageId);
        } catch (error) {
            console.error('Erreur lors de la modification du message:', error);
            throw error;
        }
    }

    // Supprimer un message (soft delete)
    async deleteMessage(messageId, userId) {
        try {
            const message = await GeneralChat.findOne({
                where: {
                    id_message: messageId,
                    id_user: userId,
                    is_deleted: false
                }
            });

            if (!message) {
                throw new Error('Message non trouvé ou vous n\'êtes pas autorisé à le supprimer');
            }

            await message.update({
                is_deleted: true,
                message: '[Message supprimé]'
            });

            return true;
        } catch (error) {
            console.error('Erreur lors de la suppression du message:', error);
            throw error;
        }
    }

    // Compter le nombre total de messages
    async getTotalMessagesCount() {
        try {
            return await GeneralChat.count({
                where: {
                    is_deleted: false
                }
            });
        } catch (error) {
            console.error('Erreur lors du comptage des messages:', error);
            throw error;
        }
    }

    // Récupérer les statistiques du chat
    async getChatStats() {
        try {
            const totalMessages = await this.getTotalMessagesCount();
            const todayMessages = await GeneralChat.count({
                where: {
                    is_deleted: false,
                    createdAt: {
                        [Op.gte]: new Date(new Date().setHours(0, 0, 0, 0))
                    }
                }
            });

            const activeUsers = await GeneralChat.count({
                distinct: true,
                col: 'id_user',
                where: {
                    is_deleted: false,
                    createdAt: {
                        [Op.gte]: new Date(Date.now() - 24 * 60 * 60 * 1000)
                    }
                }
            });

            return {
                totalMessages,
                todayMessages,
                activeUsers
            };
        } catch (error) {
            console.error('Erreur lors de la récupération des statistiques:', error);
            throw error;
        }
    }

    // Rechercher des messages
    async searchMessages(query, limit = 20) {
        try {
            return await GeneralChat.findAll({
                where: {
                    is_deleted: false,
                    message: {
                        [Op.like]: `%${query}%`
                    }
                },
                include: [
                    {
                        model: User,
                        attributes: ['id_user', 'pseudo', 'photo'],
                        as: 'user'
                    }
                ],
                order: [['createdAt', 'DESC']],
                limit: limit
            });
        } catch (error) {
            console.error('Erreur lors de la recherche de messages:', error);
            throw error;
        }
    }
}

module.exports = new GeneralChatRepository();
